TOURS_B = [
 dict(id=3393, url='sahara-desert-adventure', name='Sahara Desert Adventure', days=3, start='Marrakech', end='Marrakech',
  img=U+'IMG_5828.jpg', kind='Desert',
  intro='Short but unforgettable: high Atlas passes, dramatic gorges and the golden Erg Chebbi dunes.',
  plan=[
  ('Marrakech | Ait Benhaddou | Ouarzazate | Kelaat Mgouna | Boumalen Dades', 'Early departure in the morning from Marrakech via the spectacular Tizi N’Tichka pass (2260 m). The beautiful mountain road with unforgettable scenery is the highest road in the country. Before Ouarzazate we pay a short visit to discover Ksar Ait Ben Haddou (UNESCO World Heritage).\n\nAfter a visit to Ouarzazate — the Hollywood of Morocco — for a brief stop at Atlas Film Studios and Kasbah Taourirt, we continue on the Road of a Thousand Kasbahs to Kelaat M’gouna. Overnight stay in a traditional hotel in Boumalen Dades.'),
  ('Boumalen Dades | Tinghir | Todra Gorges | Erfoud | Dunes of Erg Chebbi (Merzouga)', 'Drive through Dades Valley and traditional Berber villages, then continue to Tinghir and stop at the famous Todra Gorge — towering cliffs over 300m high beside lush palm groves. We proceed via Erfoud, land of fossils and palm oases, toward the dunes of Merzouga.\n\nEnjoy the ever-changing colors of the desert; then mount camels for a peaceful trek into the heart of Erg Chebbi. Watch a magical sunset over the dunes and spend the night in a luxury tent under a starry sky with traditional dinner and music.'),
  ('Erg Chebbi | Alnif – Nkob | Ouarzazate | Marrakech', 'Rise early for sunrise over the dunes and a final camel ride back to the village. After breakfast, set out by car through ever-changing landscapes — oases, plateaus and rocky passes. Travel via Alnif and Nkob, cross the Draa valley region, then return to Ouarzazate and climb Tizi N’Tichka pass back to Marrakech, arriving in the afternoon/evening. End of the Sahara Desert Adventure.'),
 ]),
 dict(id=3390, url='marrakech-enchantment', name='Marrakech Enchantment', days=6, start='Marrakech', end='Marrakech',
  img=U+'pexels-mographe-15360688-scaled.jpg', kind='City & culture',
  intro='6 days of culture, cuisine, and scenic wonders. Immerse yourself in the rhythm of Marrakech with a perfect blend of cultural discovery, culinary delights, and scenic adventures.',
  note='The itinerary can be modified as much as you like.',
  plan=[
  ('Marrakech | Arrival day', 'Welcome to Marrakech, the vibrant heart of Morocco, where the city’s rich history, vibrant souks, and stunning architecture await you! Keep your eyes peeled at Menara Airport for the sign with your name or company name. Meet your driver, who will assist you and transfer you to your hotel or riad.'),
  ('Marrakech city tour (guided tour)', 'Depart from your hotel. Your introduction to Marrakech begins in the Medina — the old quarter of the city. We’ll explore this historically charming area by foot.\n\nIn Jemaa El Fna, visit the famous 12th-century Koutoubia Mosque and its influential minaret. Your guide will lead you through the labyrinth of alleys and souks filled with the scent of spices and the sound of artisans at work.\n\nEnjoy fresh orange juice, and discover shops selling Berber carpets, silver jewelry, handmade shoes, and leather goods. Then drive to the Lower Medina to explore El Mansour Mosque, the Saadian Tombs, and the ruined 16th-century El Badii Palace. Visit the Mellah and Jewish Quarter.\n\nAfter a traditional three-course lunch, continue to Bahia Palace — a 19th-century masterpiece of Moroccan architecture built for Si Moussa, a former slave who rose to power. Then visit the Dar Si Said Museum and Tiskiwin Museum, showcasing Moroccan art and craftsmanship.\n\nIn the evening, attend the Chez Ali Fantasia dinner and music show. Return to your riad for the night.'),
  ('Majorelle Garden | Anima Garden', 'This morning, visit the famous Majorelle Garden — a peaceful haven filled with over 300 plant species, small canals, and a tranquil pool surrounded by vibrant blue walls. Explore the Berber Museum to learn about Morocco’s indigenous heritage.\n\nNext, drive 45 minutes to Anima Garden, created by Austrian artist André Heller — a magical three-hectare garden filled with art installations, sculptures, and views of the snow-capped Atlas Mountains. Return to Marrakech in the afternoon and enjoy free time.\n\nIn the evening, relax with a Moroccan Hammam Spa experience.'),
  ('Day trip to Essaouira', 'Start your day trip with a scenic drive to the charming coastal town of Essaouira. Explore the medina — a UNESCO World Heritage Site — with its narrow alleys, artisan shops, and fortified ramparts.\n\nVisit the Skala de la Ville and enjoy panoramic ocean views. Walk through the fishing port to watch blue boats and fishermen at work, then savor fresh seafood at a local restaurant.\n\nAlong the way, you’ll stop at argan tree fields to see goats climbing branches and visit a women’s cooperative producing argan oil for both culinary and cosmetic use.\n\nUpon arrival in Essaouira, enjoy free time on the beach and wander along the seafront promenade. Later in the afternoon, return to Marrakech, admiring the scenic sunset views on the way.'),
  ('Cooking classes', 'Get ready for an unforgettable Moroccan culinary experience! Learn to prepare authentic dishes under the guidance of an expert chef.\n\nYou’ll discover the traditional use of herbs and spices, then cook three types of tagines, couscous, three Moroccan salads, two surprise desserts, and refreshing organic juices. End the session by enjoying the meal you’ve prepared — a true taste of Moroccan hospitality.'),
  ('Day trip to Ourika Valley', 'Depart from your hotel at 9:00 am for a scenic drive along the Ourika River, passing through lush green valleys and Berber villages.\n\nMeet your local guide and enjoy a trek to the stunning waterfalls of Setti Fatma. Relax by the river and enjoy lunch in a traditional restaurant surrounded by nature.\n\nAs the day ends, return to Marrakech with hearts full of the valley’s beauty and tranquility.'),
 ]),
 dict(id=3362, url='moroccan-historical-cities-tour', name='Moroccan Historical Cities Tour', days=8, start='Casablanca', end='Casablanca',
  img=U+'MXLU7731.jpg', kind='Imperial cities',
  intro='Discover Morocco’s historical treasures from Casablanca to Marrakech through this cultural journey that highlights imperial cities, ancient ruins, and royal landmarks.',
  plan=[
  ('Casablanca', 'Pick up at the Casablanca airport and transfer to your hotel.\n\n► Hassan II Mosque\nYou can start your day visiting the famous Hassan II Mosque, the largest religious building in the world open to non-Muslims. Its magnificent design combines modern engineering and traditional Moroccan craftsmanship.\n\n► Old Medina\nWalk through the souk in the old medina, passing Bab Marrakech and its charming small hotels built during the protectorate. Discover the authentic daily life of locals.\n\n► United Nations Square\nA vibrant hub connecting the old and modern parts of Casablanca — surrounded by shops, cafés, and historic hotels like Hyatt Regency.\n\n► The Corniche & Morocco Mall\nVisit the seaside promenade of Ain Diab, filled with cafés, beaches, and the Morocco Mall — Africa’s second-largest shopping center.'),
  ('Casablanca | Rabat', 'After breakfast, depart to Rabat — Morocco’s political and administrative capital.\n\nVisit the Kasbah of the Udayas, the Mausoleum of Mohammed V, and the impressive Hassan Tower. Stroll through the Andalusian Gardens and the charming medina filled with artisan shops.\n\nExplore the Chellah Necropolis, an ancient Roman site later used as a royal burial ground. Overnight stay in Rabat.'),
  ('Rabat | Meknes | Fes', 'After breakfast, drive to Meknes, one of Morocco’s imperial cities. Begin your visit at Bab Mansour, the grand gate facing El Hedim Square. Explore the Dar Jamaï Museum, showcasing traditional Moroccan arts, woodwork, and ceramics.\n\nLater, continue to Fes, the country’s oldest imperial city, and check in at your traditional riad.'),
  ('Fes | Moulay Idriss | Volubilis', 'Depart for a two-hour drive to explore Volubilis, Morocco’s most famous Roman ruins and a UNESCO World Heritage Site. Discover ancient mosaics, temples, and arches that tell the story of Roman civilization in North Africa.\n\nContinue to the holy town of Moulay Idriss, beautifully perched on twin hills, and enjoy panoramic views. Return to Fes for dinner and overnight stay.'),
  ('Explore Fes', 'After breakfast, begin a full-day guided tour of Fes, Morocco’s cultural and spiritual heart.\n\nVisit the Bou Inania Madrasa, Kairaouine Mosque and University, Nejjarine Fountain, and the famous tanneries. Explore the Jewish quarter (Mellah) and see the coexistence of different communities.\n\nDiscover key sites such as:\n- Medersa Bou Inania\n- University of Al Karaouine\n- Medersa el Attarin\n- Zaouia Moulay Idriss II\n- Dar Batha Museum\n\nSpend the evening relaxing in your riad or exploring the medina at leisure.'),
  ('Fes | Beni Mellal | Marrakech', 'Travel through the Middle Atlas Mountains toward Beni Mellal, surrounded by olive and orange groves. Stop for a traditional Berber lunch and explore the area’s scenic waterfalls and old kasbahs.\n\nContinue through Kasba Tadla, a garrison town built by Moulay Ismail in the 17th century, before arriving in Marrakech in the evening. Overnight stay in Marrakech.'),
  ('Tour of Marrakech', 'Discover Marrakech, the “Red City,” starting with the Koutoubia Mosque and the vibrant Jemaa El Fna square. Wander through the souks filled with carpets, spices, jewelry, and crafts.\n\nVisit:\n- Saadian Tombs\n- El Badii Palace\n- Bahia Palace\n- Mellah (Jewish Quarter)\n- Majorelle Gardens\n\nEnjoy a delicious lunch and conclude the evening with the Chez Ali Fantasia dinner show before returning to your riad.'),
  ('Marrakech | Casablanca', 'After breakfast, transfer back to Casablanca for your departure flight.\nYour Morocco Historical Cities Tour comes to an end — with unforgettable memories and experiences.'),
 ]),
]
